function dependenciesValid(nodes: string[], edges: Array<[string,string]>): boolean {
  const n = nodes.length;
  if (n === 0) {
    return true;
  }
  const seen = new Set<string>();
  for (const node of nodes) {
    if (seen.has(node)) {
      return false;
    }
    seen.add(node);
  }
  const adj: Map<string, string[]> = new Map();
  for (const [from, to] of edges) {
    if (!adj.has(from)) {
      adj.set(from, []);
    }
    adj.get(from)!.push(to);
  }
  const visited = new Set<string>();
  function dfs(node: string): boolean {
    if (visited.has(node)) {
      return false;
    }
    visited.add(node);
    for (const neighbor of adj.get(node)!) {
      if (!dfs(neighbor)) {
        return false;
      }
    }
    return true;
  }
  for (const node of nodes) {
    if (!visited.has(node)) {
      if (!dfs(node)) {
        return false;
      }
    }
  }
  return true;
}

export function dependenciesValid(nodes: string[], edges: Array<[string,string]>): boolean {
  return dependenciesValid(nodes, edges);
}

